class Solution {
    public int lengthOfLIS(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];                          // dp[i]：以 nums[i] 结尾的 LIS 长度
        Arrays.fill(dp, 1);
        int best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1); // 接在 nums[j] 后面
                }
            }
            best = Math.max(best, dp[i]);
        }
        return best;
    }
}

