class Solution {
    public int lengthOfLIS(int[] nums) {
        List<Integer> tails = new ArrayList<>();        // tails[k]：长度 k+1 的递增子序列的最小结尾
        for (int x : nums) {
            int lo = 0, hi = tails.size();              // 二分找第一个 >= x 的位置
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (tails.get(mid) < x) lo = mid + 1;
                else hi = mid;
            }
            if (lo == tails.size()) tails.add(x);       // 比所有结尾都大，接在最后
            else tails.set(lo, x);                      // 换成更小的结尾
        }
        return tails.size();
    }
}

