public:
    int lengthOfLIS(vector<int>& nums) {
        vector<int> tails;                              // tails[k]：长度 k+1 的递增子序列的最小结尾
        for (int x : nums) {
            auto it = lower_bound(tails.begin(), tails.end(), x);  // 第一个 >= x 的位置
            if (it == tails.end()) tails.push_back(x);  // 比所有结尾都大，接在最后
            else *it = x;                               // 换成更小的结尾
        }
        return tails.size();
    }
};

